package io.airtap.preview;
import android.content.*;import android.app.*;import android.os.*;import android.view.accessibility.*;import android.accessibilityservice.*;import java.util.*;
public final class SessionRecoveryGateTest {
 static final Context c=new Context();static ActivityManager activity;static UserManager user;static AccessibilityManager accessibility;static Prefs prefs;static int count;
 static class Prefs implements SharedPreferences {Map<String,Long> memory=new HashMap<>(),disk=new HashMap<>();boolean fail;public long getLong(String n,long d){return memory.getOrDefault(n,d);}public Editor edit(){return new Editor(){Map<String,Long> changes=new HashMap<>();public Editor putLong(String n,long v){changes.put(n,v);return this;}public boolean commit(){memory.putAll(changes);if(fail)return false;disk.putAll(changes);return true;}};}}
 interface Test{void run()throws Exception;}static void require(boolean b){if(!b)throw new AssertionError();}
 static void test(String n,Test t)throws Exception{activity=new ActivityManager();user=new UserManager();accessibility=new AccessibilityManager();prefs=new Prefs();Context.services.clear();Context.services.put(ActivityManager.class,activity);Context.services.put(UserManager.class,user);Context.services.put(AccessibilityManager.class,accessibility);Context.prefs=prefs;var f=SessionRecoveryGate.class.getDeclaredField("acknowledgementFailed");f.setAccessible(true);f.setBoolean(null,false);t.run();count++;System.out.println("PASS "+n);}
 public static void main(String[] a)throws Exception{
 test("only this configured accessibility component qualifies and locked boot stays closed",()->{require(!SessionRecoveryGate.operationConfigured(c));accessibility.enabled.add(new AccessibilityServiceInfo("fixture/OtherService"));require(!SessionRecoveryGate.operationConfigured(c));accessibility.enabled.add(new AccessibilityServiceInfo("fixture/io.airtap.preview.PreviewService"));require(SessionRecoveryGate.operationConfigured(c));user.unlocked=false;require(!SessionRecoveryGate.operationConfigured(c));});
 test("SIGKILL and ordinary exits do not imply explicit stop",()->{activity.exits.add(new ApplicationExitInfo(2,900));activity.exits.add(new ApplicationExitInfo(3,1000));require(!SessionRecoveryGate.userStopped(c));});
 test("explicit user stop is durable across history eviction and only foreground acknowledgement clears",()->{activity.exits.add(new ApplicationExitInfo(10,100));require(SessionRecoveryGate.userStopped(c));activity.exits.clear();require(SessionRecoveryGate.userStopped(c));SessionRecoveryGate.acknowledgeForegroundStart(c);require(!SessionRecoveryGate.userStopped(c));activity.exits.add(new ApplicationExitInfo(10,200));require(SessionRecoveryGate.userStopped(c));});
 test("exit history failure closes recovery instead of treating unknown as allowed",()->{activity.fail=true;require(SessionRecoveryGate.userStopped(c));SessionRecoveryGate.acknowledgeForegroundStart(c);activity.fail=false;require(SessionRecoveryGate.userStopped(c));SessionRecoveryGate.acknowledgeForegroundStart(c);require(!SessionRecoveryGate.userStopped(c));});
 test("failed stop persistence stays closed despite mutated preference memory",()->{activity.exits.add(new ApplicationExitInfo(10,100));prefs.fail=true;require(SessionRecoveryGate.userStopped(c));require(SessionRecoveryGate.userStopped(c));});
 test("failed acknowledgement stays closed until a successful foreground retry",()->{activity.exits.add(new ApplicationExitInfo(10,100));require(SessionRecoveryGate.userStopped(c));prefs.fail=true;SessionRecoveryGate.acknowledgeForegroundStart(c);require(SessionRecoveryGate.userStopped(c));prefs.fail=false;SessionRecoveryGate.acknowledgeForegroundStart(c);require(!SessionRecoveryGate.userStopped(c));});
 test("latest explicit stop wins regardless of record order",()->{activity.exits.add(new ApplicationExitInfo(10,300));activity.exits.add(new ApplicationExitInfo(10,100));require(SessionRecoveryGate.userStopped(c));SessionRecoveryGate.acknowledgeForegroundStart(c);require(prefs.getLong("user_start_ack",0)==300&&!SessionRecoveryGate.userStopped(c));});
 test("missing platform services fail closed",()->{Context.services.clear();require(!SessionRecoveryGate.operationConfigured(c)&&SessionRecoveryGate.userStopped(c));});
 System.out.println("TOTAL "+count);
 }
}
